// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();
        vm.prank(address(actor));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok ? address(c).balance > 0 ? false : true : true
            ? !ok || address(actor).balance >= amount
            : false,
            "withdrawAll to a rejecting recipient must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}
